@import '../../utils/interaction-fill.css';
@import '../../utils/control-inactive.css';
@import '../../utils/forced-colors.css';
:host {
  display: flex;
  flex-direction: column;
  gap: var(--dimension-space-100);
}
:host(.radio-tiles--horizontal) {
  flex-direction: row;
  flex-wrap: wrap;
}
:host(.radio-tiles--horizontal) .radio-tile {
  flex-basis: var(--dimension-menu-width-xs);
}
.radio-tile {
  display: flex;
  position: relative;
  align-items: flex-start;
  flex: 1;
  box-sizing: border-box;
  gap: var(--dimension-space-150);
  padding: var(--dimension-space-200);
  min-width: 0;
  border-radius: var(--dimension-radius-025);
  background: var(--color-background-primary);
  cursor: pointer;
  user-select: none;
}
.radio-tile__outline {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  box-shadow: inset 0 0 0 var(--dimension-stroke-width-012) var(--color-border-secondary);
  pointer-events: none;
}
:host([aria-invalid='true']) .radio-tile__outline {
  box-shadow: inset 0 0 0 var(--dimension-stroke-width-025) var(--color-border-bold-negative);
}
.radio-tile__input {
  position: absolute;
  inset: 0;
  opacity: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  cursor: inherit;
  z-index: 3;
}
.radio-tile__input:disabled {
  cursor: not-allowed;
}
.radio-tile__input:focus-visible + .radio-tile__outline {
  outline: var(--dimension-stroke-width-025) solid var(--color-interaction-focus);
  outline-offset: var(--dimension-space-025);
}
.radio-tile__placement {
  display: flex;
  align-items: center;
  justify-content: center;
  flex: none;
  width: var(--dimension-iconography-md);
  height: var(--dimension-iconography-md);
}

.radio-tile__indicator {
  display: flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  width: var(--dimension-iconography-sm);
  height: var(--dimension-iconography-sm);
  border-radius: var(--dimension-radius-half);
  box-shadow: inset 0 0 0 var(--dimension-stroke-width-015) var(--color-foreground-tertiary);
}
.radio-tile--selected .radio-tile__indicator {
  background: var(--color-background-bold-brand);
  box-shadow: none;
}
.radio-tile__indicator > span {
  width: var(--dimension-size-100);
  height: var(--dimension-size-100);
  border-radius: var(--dimension-radius-half);
  background: var(--color-foreground-on-bold-background-primary);
}
.radio-tile__copy {
  display: grid;
  gap: var(--dimension-space-050);
  min-width: 0;
}

@media (forced-colors: active) {
  .radio-tile__outline,
  .radio-tile__indicator {
    border: var(--dimension-stroke-width-012) solid var(--ds-forced-color-content);
    box-shadow: none;
  }
  .radio-tile--selected .radio-tile__indicator {
    background: var(--ds-forced-color-selected);
  }
  .radio-tile__indicator > span {
    background: var(--ds-forced-color-on-selected);
  }
}

import {
  AttachInternals,
  Component,
  Element,
  Event,
  EventEmitter,
  Prop,
  State,
  Watch,
  Method,
  h,
  Host,
} from '@stencil/core';
import {
  DEFAULT_REQUIRED_MESSAGE,
  restoreStringFormState,
  setFormControlValue,
  setRequiredValidity,
} from '../../utils';

export interface RadioTileOption {
  value: string;
  label: string;
  description?: string;
  isInactive?: boolean;
}
let tileId = 0;

@Component({ tag: 'ds-radio-tile', styleUrl: 'RadioTile.css', scoped: true, formAssociated: true })
export class RadioTile {
  @Element() el!: HTMLElement;
  @AttachInternals() internals!: ElementInternals;
  /** One-of-many choices displayed as fully clickable tiles. */
  @Prop() options: RadioTileOption[] = [];
  @Prop({ mutable: true }) value: string = '';
  @Prop({ reflect: true }) name: string | undefined;
  @Prop({ reflect: true }) form: string | undefined;
  @Prop({ reflect: true }) disabled: boolean = false;
  @Prop() isInactive: boolean = false;
  @Prop({ reflect: true }) required: boolean = false;
  @Prop() requiredMessage: string = DEFAULT_REQUIRED_MESSAGE;
  @Prop() direction: 'horizontal' | 'vertical' = 'vertical';
  @Prop() inputId: string | undefined;
  @Prop() error: boolean = false;
  @Prop({ attribute: 'aria-label' }) ariaLabel: string | null = null;
  @Prop({ attribute: 'aria-labelledby' }) ariaLabelledby: string | undefined;
  @Prop({ attribute: 'aria-describedby' }) ariaDescribedby: string | undefined;
  @Event() dsChange!: EventEmitter<string>;
  @State() private formDisabled = false;
  private readonly generatedId = `ds-radio-tile-${++tileId}`;
  private initialValue = '';
  private get inactive() {
    return this.disabled || this.isInactive || this.formDisabled;
  }
  componentWillLoad() {
    this.initialValue = this.value;
    this.syncFormValue();
  }
  @Watch('value')
  @Watch('options')
  @Watch('disabled')
  @Watch('isInactive')
  @Watch('required')
  @Watch('requiredMessage')
  syncFormValue() {
    const selected = this.options.some(option => option.value === this.value && !option.isInactive);
    setFormControlValue(this.internals, selected ? this.value : '', {
      inactive: this.inactive,
      state: this.value,
    });
    setRequiredValidity(
      this.internals,
      this.required && !this.inactive && !selected,
      this.requiredMessage
    );
  }
  formDisabledCallback(disabled: boolean) {
    this.formDisabled = disabled;
    this.syncFormValue();
  }
  formResetCallback() {
    this.value = this.initialValue;
  }
  formStateRestoreCallback(state: string | File | FormData | null) {
    this.value = restoreStringFormState(state);
  }
  @Method()
  async setFocus() {
    (
      this.el.querySelector<HTMLInputElement>('input:checked:not(:disabled)') ??
      this.el.querySelector<HTMLInputElement>('input:not(:disabled)')
    )?.focus();
  }
  private select(value: string) {
    if (this.inactive || value === this.value) return;
    this.value = value;
    this.dsChange.emit(value);
  }
  render() {
    return (
      <Host
        role="radiogroup"
        aria-label={this.ariaLabel}
        aria-labelledby={this.ariaLabelledby}
        aria-describedby={this.ariaDescribedby}
        aria-required={this.required ? 'true' : undefined}
        aria-invalid={this.error ? 'true' : undefined}
        class={{ 'radio-tiles': true, 'radio-tiles--horizontal': this.direction === 'horizontal' }}
      >
        {this.options.map((option, index) => {
          const selected = option.value === this.value;
          const inactive = this.inactive || Boolean(option.isInactive);
          return (
            <label
              class={{
                'radio-tile': true,
                'radio-tile--selected': selected,
                'ds-interaction-fill': !inactive,
                'ds-control-inactive': inactive,
              }}
              key={option.value}
            >
              <input
                type="radio"
                class="radio-tile__input"
                id={index === 0 ? this.inputId : undefined}
                name={this.generatedId}
                form=""
                value={option.value}
                checked={selected}
                disabled={inactive}
                aria-labelledby={`${this.generatedId}-label-${index}`}
                aria-describedby={
                  option.description ? `${this.generatedId}-description-${index}` : undefined
                }
                onChange={() => this.select(option.value)}
              />
              <span class="radio-tile__outline" aria-hidden="true" />
              <span class="radio-tile__placement ds-interaction-fill__content" aria-hidden="true">
                <span class="radio-tile__indicator">{selected && <span />}</span>
              </span>
              <span class="radio-tile__copy ds-interaction-fill__content">
                <ds-text
                  as="span"
                  variant="text-body-medium"
                  color={option.description ? 'primary' : 'secondary'}
                  emphasis={Boolean(option.description)}
                  textId={`${this.generatedId}-label-${index}`}
                >
                  {option.label}
                </ds-text>
                {option.description && (
                  <ds-text
                    as="span"
                    variant="text-body-medium"
                    color="secondary"
                    textId={`${this.generatedId}-description-${index}`}
                  >
                    {option.description}
                  </ds-text>
                )}
              </span>
            </label>
          );
        })}
      </Host>
    );
  }
}
